ALTER TABLE `catalog_items` ADD `service_options_json` text DEFAULT '[]' NOT NULL;--> statement-breakpoint
UPDATE `catalog_items` SET `description` = 'Transportación privada en Suburban para traslados, eventos y recorridos con comodidad y atención directa.', `service_options_json` = '[{"id":"traslado-ciudad","name":"Traslado en la ciudad","description":"Servicio privado punto a punto dentro de Mazatlán con chofer.","price":2000,"unit":"por traslado","tag":"Cómodo y privado","features":["Chofer incluido","Aire acondicionado","Hasta 6 pasajeros"],"active":true},{"id":"servicio-redondo","name":"Servicio redondo","description":"Traslado de ida y regreso para cenas, eventos o recorridos especiales.","price":3800,"unit":"servicio redondo","tag":"Más solicitado","features":["Ida y regreso","Chofer incluido","Horario coordinado"],"active":true},{"id":"renta-dia","name":"Renta por 24 horas","description":"Suburban privada para grupos, eventos y recorridos durante todo el día.","price":7500,"unit":"por 24 horas","tag":"Día completo","features":["Hasta 6 pasajeros","Aire acondicionado","Atención personalizada"],"active":true}]' WHERE `id` = 'suburban';--> statement-breakpoint
UPDATE `catalog_items` SET `description` = 'Elige un paseo por el Malecón o una ruta guiada para conocer los paisajes de Mazatlán con adrenalina.', `service_options_json` = '[{"id":"malecon-hora","name":"Paseo por el Malecón","description":"Recorre el Malecón y los puntos más llamativos de Mazatlán a tu ritmo.","price":1500,"unit":"por hora","tag":"Desde 1 hora","features":["RZR para 4 pasajeros","Casco incluido","Entrega coordinada"],"active":true},{"id":"ruta-guiada-6k","name":"Ruta guiada esencial","description":"Aventura guiada por caminos y paisajes cercanos a Mazatlán.","price":6000,"unit":"por ruta","tag":"Ruta guiada","features":["Guía durante el recorrido","Equipo de seguridad","Paradas para fotografías"],"active":true},{"id":"ruta-guiada-7k","name":"Ruta guiada completa","description":"Una experiencia más larga con recorrido, paradas y atención personalizada.","price":7000,"unit":"por ruta","tag":"Experiencia completa","features":["Guía durante el recorrido","Ruta extendida","Equipo de seguridad"],"active":true}]' WHERE `id` = 'rzr';--> statement-breakpoint
UPDATE `catalog_items` SET `description` = 'Renta una moto acuática por tiempo y disfruta velocidad, mar y vistas frente a Mazatlán.', `service_options_json` = '[{"id":"jetski-30","name":"Paseo de 30 minutos","description":"Ideal para probar la experiencia y sentir la velocidad en el mar.","price":1500,"unit":"30 minutos","tag":"Más elegido","features":["Chaleco salvavidas","Instrucciones de uso","Atención en playa"],"active":true},{"id":"jetski-60","name":"Paseo de 1 hora","description":"Más tiempo para disfrutar el recorrido y compartir la experiencia.","price":2800,"unit":"1 hora","tag":"Mejor valor","features":["Chaleco salvavidas","Instrucciones de uso","Combustible incluido"],"active":true},{"id":"jetski-120","name":"Paseo de 2 horas","description":"Paquete extendido para vivir una aventura completa frente a Mazatlán.","price":5000,"unit":"2 horas","tag":"Experiencia extendida","features":["Chaleco salvavidas","Combustible incluido","Horario reservado"],"active":true}]' WHERE `id` = 'jetski';--> statement-breakpoint
UPDATE `catalog_items` SET `description` = 'Una experiencia diferente para manejar sobre el agua y crear contenido inolvidable.', `service_options_json` = '[{"id":"jetcar-base","name":"Experiencia Jetcar","description":"Maneja sobre el agua con estilo deportivo y atención personalizada.","price":3500,"unit":"por experiencia","tag":"Diversión extrema","features":["Chaleco salvavidas","Instrucciones de uso","Atención en playa"],"active":true}]' WHERE `id` = 'jetcar';--> statement-breakpoint
